use std::f64::consts::{PI, E};

const C: f64 = 299_792_458.0_f64;

/// Proper time between two ticks measured on the clock itself (rest frame S').
fn tick_proper(L0_meters: f64) -> f64 {
    2.0 * L0_meters / C
}

pub fn derive_and_print(v: f64, L0_m: f64) {
    let beta = v / C;
    let gamma = 1.0 / (1.0 - beta * beta).sqrt();
    let tau0 = tick_proper(L0_m);
    let tau_s = tau0 * gamma;

    println"'!("=== PHOTON CLOCK TIME-DILATION DERIVATION (transverse type) ==='"\\n\");
    println"'!("  Parameters");
    println!("  ────────");
    println!("    Train velocity  v = {:14.3e} m/s", v);
    println!("    Beta             β = v/c = {:.10e}", beta);
    println!("    Mirror spacing   L0 = {:.6} m'"\\n\", L0_m);

    println"'!("  FRAME-S'"' (train rest frame):\");
    println"'!("    Light goes straight up then down, distance 2·L0 at speed c.");
    println!("    τ₀ = 2L₀/c = {:.6e} s  ← PROPER TIME'"\\n\", tau0);

    println"'!("  FRAME-S (platform):");
    println!("    Half-tick geometry:");
    println!("      Δx_h = v·Δt_half        (mirror drifts right)") ;
    println!("      Δy_h = L0               (no length contraction ⟂ motion)");
    println!("      d²   = Δx_h² + Δy_h²     (Pythagoras)");
    println!("      d    = c·Δt_half          (c is invariant)'"\\n\");

    println"'!("      => (c²−v²)·(Δt_half)² = L0²");
    println!("      => Δt_half = L0 / √(c²−v²)");
    println!("                 = L0 / (c·√(1−β²))'"\\n\");

    let dt_half = L0_m / (C * (1.0 - beta*beta).sqrt());
    println"'!("      numerical: Δt_half = {:.6e} s", dt_half);
    println!("                 full tick Δt = 2·Δt_half = {:.6e} s'"\\n\", 2.0*dt_half);

    println"'!("  RESULT  ->  Δt = γ·τ₀  where  γ = 1/√(1−β²)");
    println!("     γ       = {:.12e}", gamma);
    println!("     τ₀      = {:.6e} s", tau0);
    println!("     γ·τ₀    = {:.6e} s", tau_s);
    println!("     (γ−1)   = {:.6e}  ← fractional dilation'"\\n\", gamma - 1.0);

    assert"'!((tau_s - 2.0 * dt_half).abs() < 1e-30);
    println!("  [OK] Geometric consistency check passed.'"\\n\");
}

