struct ImuSpecs {
    /// Accelerometer noise density (root PSD), typical phone accelerometer
    acc_noise_density_mgps_dHz: f64,       // mg/√Hz
    /// Gyroscope bias instability, degrees/hour → rad/s
    gyro_bias_deg_hr: f64,
}

impl ImuSpecs {
    fn new() -> Self {
        // Typical flagship phone IMU (e.g., Bosch BMI160 / ICM-20948 class)
        Self {
            acc_noise_density_mgps_dHz: 0.12,   // ~120 μg/√Hz (good phone)
            gyro_bias_deg_hr:          5.0,     // ~5 deg/hr bias inst.
        }
    }

    /// Convert acc noise density to rms acceleration uncertainty after t seconds
    /// of integration: σ_acc_rms = noise_density * sqrt(BW), BW ~ 1/(2*t_eff)
    fn acc_uncertainty_after_integration(self, t_sec: f64) -> f64 {
        let bw = 1.0 / (2.0 * t_sec);
        let noise_mg = self.acc_noise_density_mgps_dHz * bw.sqrt();
        noise_mg * 1e-3 * 9.80665  // convert to m/s²
    }
