const C: f64 = 299_792_458.0_f64;

// Consumer-spec parameters
struct ImuSpecs {
    acc_noise_density_mg_dHz: f64, // mg/sqrt(Hz)
    gyro_bias_deg_hr: f64,
}

impl ImuSpecs {
    fn new() -> Self {
        Self {
            acc_noise_density_mg_dHz: 0.12, // ~120 uG/sqrt(Hz) for good phone IMU
            gyro_bias_deg_hr: 5.0,          // typical bias instability
        }
    }

    // Accelerometer RMS uncertainty after t seconds integration
    fn acc_rms_after(self, t_sec: f64) -> f64 {
        let bw = 1.0 / (2.0 * t_sec);
        self.acc_noise_density_mg_dHz * bw.sqrt() * 1e-3 * 9.80665
    }
