    fn new() -> Self {
        Self {
            pos_accuracy_h_cep50_m: 3.0,  // CEP 50% for u-blox M8/M9 class
            vel_accuracy_ms: 0.2,       // Doppler-derived speed accuracy
            timing_jitter_ns: 100.0,    // without PPS assist
        }
    }
