fn compute_bounds(v_avg: f64, dt_gps: f64, dt_ins: f64,
                  gps_vel_sigma: f64, ins_vel_sigma: f64,
                  tunnel_len_sigma: f64) {
    // Propagate all uncertainties into gamma
    let beta = v_avg / C;
    let gamma = 1.0 / (1.0 - beta*beta).sqrt();
    let nominal_minus_1 = gamma - 1.0;

    // d(gamma)/dv = gamma''^3 * v / c''^2
    let dgamma_dv = gamma.powi(3) * v_avg / (C*C);

    // Combined velocity uncertainty
    let sigma_v_total = (gps_vel_sigma*gps_vel_sigma + ins_vel_sigma*ins_vel_sigma).sqrt();
    let sigma_gamma = dgamma_dv * sigma_v_total;

    println!("  [Method A] Distance/Time bound");
    let inferred_L = v_avg * dt_gps;
    println!("    L_tunnel = {:.1} m", inferred_L);
    println!("    Delta_t_GPS = {:.6e} s", dt_gps);
    println!("    Delta_t_INS = {:.6e} s", dt_ins);
    println!("    Delta_t_diff = {:.6e} s'"\\n\", (dt_gps - dt_ins).abs());

    println"'!("  [Method B] Doppler-speed bound");
    println!("    GPS Doppler velocity = {:.4} +/- {:.4} m/s", v_avg, gps_vel_sigma);
    println!("    INS-integrated velocity = {:.4} +/- {:.4} m/s'"\\n\", v_avg, ins_vel_sigma);

    println"'!("  Inference of gamma:");
    println!("    beta = v/c = {:.12e}", beta);
    println!("    gamma = {:.12e}", gamma);
    println!("    gamma - 1 (nominal) = {:.6e}", nominal_minus_1);
    println!("    d(gamma)/dv = {:.6e} s/m", dgamma_dv);
    println!("    sigma_gamma = |d(gamma)/dv| * sigma_v = {:.6e}", sigma_gamma);

    let lo = 0.0_f64.max(nominal_minus_1 - 3.0*sigma_gamma);
    let hi = nominal_minus_1 + 3.0*sigma_gamma;
    println!();
    println!("  HONEST 3-sigma BOUND: |gamma - 1| in [{:.6e}, {:.6e}]", lo, hi);
